import { Button } from "march/ui"
import type { IconType } from "march/icons"

// bugünün havası: üç hap düğme, seçili olan basılı durur
// Mood'un icon'u IconType: tırnak içinde editör ikon listesini açar (March'ın adları ve paketler);
// derleyici her adı o tek ikonun import'una çevirir, pakete yalnız kullanılanlar girer
interface Mood {
  id: string
  label: string
  icon: IconType
}

const moods: Mood[] = [
  { id: "sun", label: "Enerjik", icon: "sun" },
  { id: "cloud", label: "Sakin", icon: "lucide:cloud-sun" },
  { id: "moon", label: "Uykulu", icon: "tabler:moon-stars" },
]

export function MoodPicker() {
  let $mood = "sun"
  return <div sx={{ flex: "row", gap: 2 }}>
    {moods.map((m) => <Button shape="pill" icon={m.icon} pressed={$mood === m.id} on:click={() => $mood = m.id}>{m.label}</Button>)}
  </div>
}

import { Button, toast } from "march/ui"
import { check, x } from "march/icons"

// bir ayarlar formunun alt çubuğu: kaydederken Kaydet kilitlenip döner, Vazgeç bekler
export function SaveBar() {
  let $saving = false
  const save = () => {
    $saving = true
    setTimeout(() => { $saving = false; toast("Değişiklikler kaydedildi") }, 1200)
  }
  return <div sx={{ flex: ["row", "end"], gap: 2 }}>
    <Button variant="ghost" icon={x} disabled={$saving}>Vazgeç</Button>
    <Button variant="primary" icon={check} loading={$saving} on:click={save}>Kaydet</Button>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ButtonLab } from "./ButtonLab.tsx"

// ButtonLab'in testleri: kaydedince Testler sekmesinde çalışır
test("Beğen'e basınca Beğenildi olur, basılı durur", async () => {
  const s = renderTest(() => <ButtonLab />)
  const like = await s.click("Beğen")
  expect(s.sees("Beğenildi")).toBe(true)
  expect(like.getAttribute("aria-pressed")).toBe("true")
})

test("Gönder her basışta sayacı bir artırır", async () => {
  const s = renderTest(() => <ButtonLab />)
  await s.click("Gönder (0)")
  await s.click("Gönder (1)")
  expect(s.text()).toContain("Gönder (2)")
})

test("Silinemez düğmesi devre dışı", () => {
  const s = renderTest(() => <ButtonLab />)
  const del = s.find("Silinemez")?.closest("button")
  expect(del?.hasAttribute("disabled")).toBe(true)
})
